Set(
    RecoveryCodeExpired,
    If(
        DateDiff(
            gblTimeCodeWasSent,
            Now(),
            TimeUnit.Minutes
        ) > 5,
        true,
        false
    )
);
Set(
    RecoveryCodeError,
    If(
        Value(txtRecoveryCode.Text) <> gblRecoveryCodeSent,
        true,
        false
    )
);
Set(
    gblRecoveryPasswordDontMatch,
    If(
        txtNewPassword.Text <> txtConfirmNewPassword.Text,
        true,
        false
    )
);
ClearCollect(
    colCheckNumbers,
    ForAll(
        Split(
            txtNewPassword.Text,
            ""
        ),
        If(
            IsMatch(
                Value,
                "[0-9]"
            ),
            Value,
            ""
        )
    )
);
ClearCollect(
    colCheckCapitalLetters,
    ForAll(
        Split(
            txtNewPassword.Text,
            ""
        ),
        If(
            IsMatch(
                Value,
                "[A-Z]"
            ),
            Value,
            ""
        )
    )
);
ClearCollect(
    colCheckSmallLetters,
    ForAll(
        Split(
            txtNewPassword.Text,
            ""
        ),
        If(
            IsMatch(
                Value,
                "[a-z]"
            ),
            Value,
            ""
        )
    )
);
ClearCollect(
    colCheckSymbol,
    ForAll(
        Split(
            txtNewPassword.Text,
            ""
        ),
        If(
            IsMatch(
                Value,
                "[@,#,$,%,&,?,>,<]"
            ),
            Value,
            ""
        )
    )
);
UpdateContext(
    {
        locNewPasswordError: (CountRows(
            Filter(
                colCheckNumbers,
                Value
            )
        ) = 0 || CountRows(
            Filter(
                colCheckCapitalLetters,
                Value
            )
        ) = 0 || CountRows(
            Filter(
                colCheckSmallLetters,
                Value
            )
        ) = 0 || CountRows(
            Filter(
                colCheckSymbol,
                Value
            )
        ) = 0)
    }
);
If(
    locNewPasswordError,
    Notify(
        "Password must be a combination of uppercase letters, lowercase letters, numbers and any of these symbols !@#$%^&*>?",
        NotificationType.Error,
        3000
    ),
    If(
        RecoveryCodeExpired,
        false;
        Notify(
            "Code has expired. Click resend for another code",
            NotificationType.Error,
            4000
        ),
        If(
            RecoveryCodeError,
            false;
            Notify(
                "Incorrect code. Try again",
                NotificationType.Error,
                4000
            ),
            If(
                gblRecoveryPasswordDontMatch,
                false;
                Notify(
                    "Passwords do not match. Please try again",
                    NotificationType.Error,
                    4000
                ),
                If(
                    locNewPasswordError,
                    false;
                    Notify(
                        "Password must be a combination of uppercase letters, lowercase letters, numbers and any of these symbols !@#$%^&*>?",
                        NotificationType.Error,
                        4000
                    )
                )
            )
        )
    )
);
If(
    RecoveryCodeExpired = false And RecoveryCodeError = false And locNewPasswordError = false And gblRecoveryPasswordDontMatch = false,
    Patch(
        LoginDemo,
        {ID: gblIDUserToBeRecovered},
        {Password: txtNewPassword.Text}
    );
    Notify(
        "Password change successful. Please login with new password",
        NotificationType.Success,
        4000
    );
    Navigate(
        HomeScreen,
        ScreenTransition.Fade
    );
    Reset(txtRecoveryCode);
    Reset(txtNewPassword);
    Reset(txtConfirmNewPassword);
    Reset(txtRecoveryEmailAddress);

)

Set(
    gblIDUserToBeRecovered,
    LookUp(
        LoginDemo,
        EmailAddress = txtRecoveryEmailAddress.Text
    ).ID
);

Set(
    gblNameUserToBeRecovered,
    LookUp(
        LoginDemo,
        EmailAddress = txtRecoveryEmailAddress.Text
    ).Titre
);

Set(
    gblTimeCodeWasSent,
    Now()
);

Set(
    gblRecoveryCodeSent,
    RandBetween(111111, 999999)
);

Office365Outlook.SendEmailV2(
    txtRecoveryEmailAddress.Text,
    "Complete Registration",
    "<div style='background-color: #f5f5f5; width: 650px; height: 400px; border: 2px solid black; padding-bottom: 30px; font-weight:600; color: #0c5c00'>
        <div style='background-color: #638b2c; height: 60px; text-align: center; color: #f5f5f5; font-weight: 900; padding: 15px; font-size: 2em; font-family: Trebuchet MS'>
            RESET PASSWORD
        </div>
        <div style='font-size: 2em; font-family: Trebuchet MS; padding: 20px; background-color: #f5f5f5; color: #057f3f'>
            <br> Hello " & gblNameUserToBeRecovered & ",<br><br> Please complete your account registration using the code below.
            <div style='background-color: #f5f5f5; height: 60px; text-align: center; color: #057f3f; font-weight: 900; padding: 15px; font-size: 2em; font-family: Trebuchet MS'>
                " & gblRecoveryCodeSent & "
            </div>
        </div>
    </div>",
    {
        Importance: "Normal",
        IsHtml: true
    }
);

Reset(txtRecoveryEmailAddress)

